text(await tools.apply_patch("*** Begin Patch\n*** Add File: game-012-log.json\n+"+JSON.stringify(g,null,2).split("\n").join("\n+")+"\n*** Add File: game-012.sgf\n+"+sgf.trim()+"\n*** End Patch"));

